#polymer = "dabAcCaCBAcCcaDA"
polymer = ""

def collapse_polymer(p: str):
    last_index = 0
    while True:
        completed = False
        if last_index > 0:
            last_index -= 1
        for i in range(last_index, len(p) - 1):
            if p[i].isupper() != p[i + 1].isupper():
                if p[i].lower() == p[i + 1].lower():
                    p = p[:i] + p[i + 2:]
                    last_index = i
                    break
            if i == len(p) - 2:
                completed = True
        if completed:
            break
    print(p)
    return len(p)

characters = "abcdefghijklmnopqrstuvwxyz"

lengths = []

for c in characters:
    modified_polymer = polymer.replace(c, '')
    modified_polymer = modified_polymer.replace(c.upper(), '')

    lengths.append(collapse_polymer(modified_polymer))

print(min(lengths))